## 3. Result-Generation Logic (form data → recommendation)

The module-specific recommendation logic is the inline `evaluate()` function (and its input/default types) in the Compass page, not in `pdfExport.ts`.

Source: `client/src/pages/PGTCompass.tsx`

```typescript
type PGTType = "pgt_a" | "pgt_m" | "pgt_sr";

interface PGTInputs {
  pgtType: PGTType;
  femaleAge: number;
  recurrentPregnancyLoss: boolean;
  rplCount: number;
  priorAneuploidPregnancy: boolean;
  knownGeneticDisorder: boolean;
  geneDisorderName: string;
  chromosomalTranslocation: boolean;
  advancedMaternalAge: boolean;
  repeatedIVFFailure: boolean;
  ivfFailureCount: number;
  oncologyIndication: boolean;
  sexSelection: boolean;
}

const defaultInputs: PGTInputs = {
  pgtType: "pgt_a", femaleAge: 0, recurrentPregnancyLoss: false, rplCount: 0,
  priorAneuploidPregnancy: false, knownGeneticDisorder: false, geneDisorderName: "",
  chromosomalTranslocation: false, advancedMaternalAge: false, repeatedIVFFailure: false,
  ivfFailureCount: 0, oncologyIndication: false, sexSelection: false,
};

function evaluate(inputs: PGTInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Practice Committee of the ASRM. The use of preimplantation genetic testing for aneuploidy (PGT-A): a committee opinion. Fertil Steril. 2018;109(3):429-436.",
    "ACOG Committee Opinion No. 682. Microarrays and Next-Generation Sequencing Technology. Obstet Gynecol. 2016;128(6):e262-e268.",
    "Munne S, et al. Preimplantation genetic testing for aneuploidy versus morphology as selection criteria for single frozen-thawed embryo transfer in good-prognosis patients. Fertil Steril. 2019;112(6):1071-1079.",
    "ASRM Practice Committee. Preimplantation genetic testing: a committee opinion. Fertil Steril. 2018;109(3):429-436.",
  ];

  let recommendation = "not_indicated";
  let procedure = "";
  let cor = "I";
  let loe = "B";

  if (inputs.pgtType === "pgt_m" && inputs.knownGeneticDisorder) {
    recommendation = "indicated";
    procedure = "PGT-M (monogenic/single gene disorder)";
    cor = "I"; loe = "A";
    rationale.push(`Known genetic disorder (${inputs.geneDisorderName || "specified"}): PGT-M is indicated to prevent transmission of serious genetic disease.`);
    rationale.push("ASRM: PGT-M is appropriate for couples at risk of transmitting serious monogenic disorders.");
  } else if (inputs.pgtType === "pgt_sr" && inputs.chromosomalTranslocation) {
    recommendation = "indicated";
    procedure = "PGT-SR (structural rearrangement — translocation)";
    cor = "I"; loe = "A";
    rationale.push("Chromosomal translocation: PGT-SR is indicated to select embryos with balanced chromosomal complement.");
  } else if (inputs.pgtType === "pgt_a") {
    const hasStrongIndication = inputs.recurrentPregnancyLoss && inputs.rplCount >= 2 ||
      inputs.priorAneuploidPregnancy || inputs.femaleAge >= 38 ||
      (inputs.repeatedIVFFailure && inputs.ivfFailureCount >= 2);
    if (hasStrongIndication) {
      recommendation = "indicated";
      procedure = "PGT-A (aneuploidy screening)";
      cor = "IIa"; loe = "B";
      if (inputs.recurrentPregnancyLoss) rationale.push(`Recurrent pregnancy loss (${inputs.rplCount} losses): PGT-A may identify aneuploid embryos contributing to pregnancy loss.`);
      if (inputs.femaleAge >= 38) rationale.push(`Advanced maternal age (${inputs.femaleAge}): higher aneuploidy rate — PGT-A may improve single embryo transfer outcomes.`);
      if (inputs.repeatedIVFFailure) rationale.push(`Repeated IVF failure (${inputs.ivfFailureCount} cycles): PGT-A may identify viable euploid embryos.`);
      warnings.push("PGT-A: ASRM notes evidence for clinical benefit is strongest in RPL and repeated IVF failure. Routine use in all IVF cycles is not universally recommended.");
    } else {
      recommendation = "consider";
      procedure = "PGT-A — consider with shared decision-making";
      cor = "IIb"; loe = "C";
      rationale.push("No strong indication for PGT-A identified. Discuss risks/benefits with patient including embryo biopsy risk and potential for inconclusive results.");
    }
  } else {
    recommendation = "not_indicated";
    procedure = "PGT not indicated based on current inputs";
  }

  if (inputs.sexSelection) {
    warnings.push("Non-medical sex selection: ASRM considers non-medical sex selection ethically controversial. Most insurers will not cover PGT for this indication.");
  }

  return { recommendation, procedure, cor, loe, warnings, rationale, references };
}
```

The assessment is rendered/exported to PDF using the shared helper below (not module-specific result logic).

Source: `client/src/lib/pdfExport.ts`

```typescript
// PDF export using browser print API

export interface PDFExportOptions {
  filename: string;
  title: string;
  content: string;
  metadata?: {
    date?: string;
    module?: string;
    [key: string]: any;
  };
}

/**
 * Export assessment results as PDF
 */
export async function exportAssessmentPDF(options: PDFExportOptions): Promise<void> {
  const { filename, title, content, metadata } = options;

  const htmlContent = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <title>${title}</title>
      <style>
        * {
          margin: 0;
          padding: 0;
          box-sizing: border-box;
        }
        body {
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', sans-serif;
          line-height: 1.6;
          color: #333;
          background: white;
          padding: 20px;
        }
        .header {
          border-bottom: 3px solid #e11d48;
          padding-bottom: 20px;
          margin-bottom: 30px;
        }
        .header h1 {
          font-size: 28px;
          color: #1e293b;
          margin-bottom: 10px;
        }
        .metadata {
          font-size: 12px;
          color: #64748b;
          display: flex;
          gap: 20px;
          flex-wrap: wrap;
        }
        .metadata-item {
          display: flex;
          gap: 5px;
        }
        .metadata-label {
          font-weight: 600;
          color: #475569;
        }
        .content {
          margin-top: 20px;
        }
        .section {
          margin-bottom: 30px;
          page-break-inside: avoid;
        }
        .section-title {
          font-size: 18px;
          font-weight: 600;
          color: #1e293b;
          border-left: 4px solid #e11d48;
          padding-left: 15px;
          margin-bottom: 15px;
          margin-top: 20px;
        }
        .section-content {
          background: #f8fafc;
          padding: 15px;
          border-radius: 6px;
          margin-bottom: 15px;
        }
        .field {
          margin-bottom: 12px;
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
        }
        .field-label {
          font-weight: 600;
          color: #475569;
          min-width: 150px;
        }
        .field-value {
          color: #1e293b;
          text-align: right;
          flex: 1;
        }
        table {
          width: 100%;
          border-collapse: collapse;
          margin: 15px 0;
        }
        th {
          background: #e2e8f0;
          padding: 10px;
          text-align: left;
          font-weight: 600;
          color: #1e293b;
          border: 1px solid #cbd5e1;
        }
        td {
          padding: 10px;
          border: 1px solid #cbd5e1;
          color: #475569;
        }
        tr:nth-child(even) {
          background: #f8fafc;
        }
        .footer {
          margin-top: 40px;
          padding-top: 20px;
          border-top: 1px solid #e2e8f0;
          font-size: 11px;
          color: #64748b;
          text-align: center;
        }
        .disclaimer {
          background: #fef2f2;
          border: 1px solid #fecaca;
          padding: 12px;
          border-radius: 4px;
          font-size: 12px;
          color: #7f1d1d;
          margin-top: 20px;
        }
        @media print {
          body {
            padding: 0;
          }
        }
      </style>
    </head>
    <body>
      <div class="header">
        <h1>${title}</h1>
        ${metadata ? `
          <div class="metadata">
            ${metadata.date ? `<div class="metadata-item"><span class="metadata-label">Date:</span> <span>${metadata.date}</span></div>` : ''}
            ${metadata.module ? `<div class="metadata-item"><span class="metadata-label">Module:</span> <span>${metadata.module}</span></div>` : ''}
          </div>
        ` : ''}
      </div>
      <div class="content">
        ${content}
      </div>
      <div class="footer">
        <p>This document was generated by Clinical Compass™. Please review and verify all information before use.</p>
      </div>
    </body>
    </html>
  `;

  const element = document.createElement('div');
  element.innerHTML = htmlContent;

  const opt = {
    margin: 10,
    filename: `${filename}.pdf`,
    image: { type: 'jpeg', quality: 0.98 },
    html2canvas: { scale: 2 },
    jsPDF: { orientation: 'portrait', unit: 'mm', format: 'a4' },
  };

  // Use html2pdf if available, otherwise use a simple approach
  try {
    if (typeof (window as any).html2pdf !== 'undefined') {
      (window as any).html2pdf().set(opt).from(element).save();
    } else {
      // Fallback: open print dialog
      const printWindow = window.open('', '', 'width=800,height=600');
      if (printWindow) {
        printWindow.document.write(htmlContent);
        printWindow.document.close();
        printWindow.print();
      }
    }
  } catch (error) {
    console.error('PDF export failed:', error);
    // Fallback: open print dialog
    const printWindow = window.open('', '', 'width=800,height=600');
    if (printWindow) {
      printWindow.document.write(htmlContent);
      printWindow.document.close();
      printWindow.print();
    }
  }
}

/**
 * Generate HTML content for assessment results
 */
export function generateAssessmentHTML(data: {
  title: string;
  demographics?: {
    age?: number;
    sex?: string;
    bmi?: number;
  };
  findings?: Array<{ label: string; value: string }>;
  recommendation?: string;
  details?: string;
}): string {
  let html = '';

  if (data.demographics) {
    html += `
      <div class="section">
        <div class="section-title">Patient Demographics</div>
        <div class="section-content">
          ${data.demographics.age ? `<div class="field"><span class="field-label">Age:</span> <span class="field-value">${data.demographics.age} years</span></div>` : ''}
          ${data.demographics.sex ? `<div class="field"><span class="field-label">Sex:</span> <span class="field-value">${data.demographics.sex}</span></div>` : ''}
          ${data.demographics.bmi ? `<div class="field"><span class="field-label">BMI:</span> <span class="field-value">${data.demographics.bmi}</span></div>` : ''}
        </div>
      </div>
    `;
  }

  if (data.findings && data.findings.length > 0) {
    html += `
      <div class="section">
        <div class="section-title">Clinical Findings</div>
        <div class="section-content">
          ${data.findings.map(f => `<div class="field"><span class="field-label">${f.label}:</span> <span class="field-value">${f.value}</span></div>`).join('')}
        </div>
      </div>
    `;
  }

  if (data.recommendation) {
    html += `
      <div class="section">
        <div class="section-title">Clinical Recommendation</div>
        <div class="section-content">
          <p>${data.recommendation}</p>
        </div>
      </div>
    `;
  }

  if (data.details) {
    html += `
      <div class="section">
        <div class="section-content">
          ${data.details}
        </div>
      </div>
    `;
  }

  html += `
    <div class="disclaimer">
      <strong>Disclaimer:</strong> This assessment is generated by Clinical Compass™ clinical decision support tool and is intended to assist physicians in clinical decision-making. It should not replace professional medical judgment. All recommendations should be reviewed and validated by the treating physician before clinical implementation.
    </div>
  `;

  return html;
}
```


